ion"},{"stateMutability":"payable","type":"receive"}],"devdoc":{"details":"This contract allows to split ERC20 and Ether tokens among a group of accounts. The sender does not need to be aware that the token(s) (revenue) will be split in this way, since it is handled transparently by the contract. The split can be in equal parts or in any other arbitrary proportion. The way this is specified is by assigning each account to a number of shares. Of all the fund this contract receives, each account will then be able to claim an amount proportional to the percentage of total shares they were assigned. `RevenueSplitter` follows a pull revenue model. This means that revenue is not automatically forwarded to the accounts but kept in this contract, and the actual transfer is triggered as a separate step by calling the {release} or {releaseEther} function.","kind":"dev","methods":{"addVToken(address,address)":{"details":"Add vToken for vesper deployer top-up","params":{"_oracle":"- Chainlink oracle address used for collateral token to ETH estimation Find chainlink oracle details here https://docs.chain.link/docs/ethereum-addresses/ For pool with WETH as collateral token, we do not need _oracle and _oracle can have ZERO address.","_vToken":"- Vesper token"}},"constructor":{"details":"Creates an instance of `RevenueSplitter` where each account in `_payees` is assigned token(s) at the matching position in the `_share` array. All addresses in `payees` must be non-zero. Both arrays must have the same non-zero length, and there must be no duplicates in `payees`.","params":{"_payees":"-  address(es) of payees eligible to receive token(s)","_share":"- list of shares, transferred to payee in provided ratio."}},"release(address,address)":{"details":"Transfer of ERC20 token(s) to `payee` based on share and their previous withdrawals.","params":{"_asset":"- ERC20 token's address","_payee":"- payee's address to receive token(s)"}},"releaseEther(address)":{"details":"Transfer of ether to `payee` based on share and their previous withdrawals.","params":{"_payee":"- payee's address to receive ether"}},"removeVToken(address)":{"details":"Remove vToken for vesper deployer top-up","params":{"_vToken":"- Vesper token"}},"sweep(address,address,uint256)":{"params":{"amount_":"The amount to send","to_":"The recipient of the transfer","token_":"The token to transfer"}},"toggleAutoTopUp()":{"details":"Toggle auto top-up to true will enable top-up too."},"toggleTopUpStatus()":{"details":"Toggle top-up status to false will disable auto top-up too."},"transferGovernorship(address)":{"details":"Can only be called by the current owner.","params":{"proposedGovernor_":"The new proposed governor"}}},"title":"RevenueSplitter","version":1},"userdoc":{"kind":"user","methods":{"acceptGovernorship()":{"notice":"Allows new governor to accept governorship of the contract."},"governor()":{"notice":"The governor"},"proposedGovernor()":{"notice":"The proposed governor"},"sweep(address,address,uint256)":{"notice":"ERC20 recovery in case of stuck tokens due direct transfers to the contract address."},"toggleAutoTopUp()":{"notice":"Toggle auto top-up"},"toggleTopUpStatus()":{"notice":"Toggle top-up status"},"topUp()":{"notice":"top-up Vesper deployer address"},"transferGovernorship(address)":{"notice":"Transfers governorship of the contract to a new account (`proposedGovernor`)."}},"version":1}},"settings":{"compilationTarget":{"contracts/RevenueSplitter.sol":"RevenueSplitter"},"evmVersion":"london","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":500},"remappings":[]},"sources":{"@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol":{"content":"// SPDX-License-Identifier: MIT
